import{_ as a,c as r,o,j as s,Y as n,t as i}from"./chunks/framework.D-NV0Bun.js";const b=JSON.parse('{"title":"stdbuf | x-cmd man (man1) | Run COMMAND. with modified buffering operations for its","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | stdbuf - Run COMMAND. with modified buffering operations for its","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"stdbuf | x-cmd man (man1) | Run COMMAND. with modified buffering operations for its"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | stdbuf - Run COMMAND. with modified buffering operations for its"}]]},"headers":[],"params":{"isMan":true,"man":"stdbuf","category":"man1","desc":"Run COMMAND. with modified buffering operations for its"},"relativePath":"man1/stdbuf.md","filePath":"man1/[man].md"}'),d={name:"man1/stdbuf.md"},l={class:"visually-hidden"};function f(e,t,u,h,p,m){return o(),r("div",null,[s("h1",l,i(e.$params.man),1),t[0]||(t[0]=n('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>stdbuf - Run COMMAND, with modified buffering operations for its standard streams.</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>stdbuf</strong> <em>OPTION</em>... <em>COMMAND</em></p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Run COMMAND, with modified buffering operations for its standard streams.</p><p>Mandatory arguments to long options are mandatory for short options too.</p><dl><dt><strong>-i</strong>, <strong>--input</strong>=<em>MODE</em></dt><dd>adjust standard input stream buffering</dd><dt><strong>-o</strong>, <strong>--output</strong>=<em>MODE</em></dt><dd>adjust standard output stream buffering</dd><dt><strong>-e</strong>, <strong>--error</strong>=<em>MODE</em></dt><dd>adjust standard error stream buffering</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><p>If MODE is &#39;L&#39; the corresponding stream will be line buffered. This option is invalid with standard input.</p><p>If MODE is &#39;0&#39; the corresponding stream will be unbuffered.</p><p>Otherwise MODE is a number which may be followed by one of the following: KB 1000, K 1024, MB 1000*1000, M 1024*1024, and so on for G,T,P,E,Z,Y,R,Q. Binary prefixes can be used, too: KiB=K, MiB=M, and so on. In this case the corresponding stream will be fully buffered with the buffer size set to MODE bytes.</p><p>NOTE: If COMMAND adjusts the buffering of its standard streams (&#39;tee&#39; does for example) then that will override corresponding changes by &#39;stdbuf&#39;. Also some filters (like &#39;dd&#39; and &#39;cat&#39; etc.) don&#39;t use streams for I/O, and are thus unaffected by &#39;stdbuf&#39; settings.</p><h3 id="exit-status" tabindex="-1">Exit status: <a class="header-anchor" href="#exit-status" aria-label="Permalink to &quot;Exit status:&quot;">​</a></h3><dl><dt>125</dt><dd>if the stdbuf command itself fails</dd><dt>126</dt><dd>if COMMAND is found but cannot be invoked</dd><dt>127</dt><dd>if COMMAND cannot be found</dd><dt>-</dt><dd>the exit status of COMMAND otherwise</dd></dl><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p><strong>tail -f access.log | stdbuf -oL cut -d &#39; &#39; -f1 | uniq</strong> <br> This will immediately display unique entries from access.log</p><h2 id="bugs" tabindex="-1">BUGS <a class="header-anchor" href="#bugs" aria-label="Permalink to &quot;BUGS&quot;">​</a></h2><p>On GLIBC platforms, specifying a buffer size, i.e., using fully buffered mode will result in undefined operation.</p><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by Padraig Brady.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p>Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/stdbuf%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/stdbuf\\</a>&gt; <br> or available locally via: info &#39;(coreutils) stdbuf invocation&#39;</p>',26))])}const c=a(d,[["render",f]]);export{b as __pageData,c as default};
